const BLOCK = [/union\s+select/i, /union\s+all\s+select/i];
if (BLOCK.some((re) => re.test(q))) return res.status(403).send('blocked');
const sql = "SELECT title, body FROM notices WHERE title LIKE '%" + q + "%'";
